package cn.zhuatech.dms.controller; import cn.zhuatech.dms.common.ApiResponse; import cn.zhuatech.dms.dto.DmsDto.*; import cn.zhuatech.dms.service.DmsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOCUMENT_MANAGER','QUALITY','ADMIN')") public class DocumentAdminController {private final DmsService dms;public DocumentAdminController(DmsService dms){this.dms=dms;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(dms.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<DocumentView>> orders(){return ApiResponse.ok(dms.documents());}}
